+            uint64_t currN = GetMatmulV3TailSize(nIdx, actualN, baseN);
+            size += ops::CeilAlign(currM, BASIC_ALIGN_16) * ops::CeilAlign(currN, BASIC_ALIGN_16);
+        }
+    }
+    return size;
+}
